import {
  test,
  expect,
  setThemePlan,
  setThemeQuotaGating,
} from "../helpers/theme-browser";
import { test as publicTest } from "../helpers/system-control-browser";
import type { Page, TestInfo } from "@playwright/test";

const themes = [
  ["Lavender", "purple", "light", "rgb(116, 71, 217)"],
  ["Nightbloom", "purple", "dark", "rgb(109, 93, 252)"],
  ["Chalk", "vercel", "light", "rgb(21, 21, 21)"],
  ["Obsidian", "vercel", "dark", "rgb(236, 236, 236)"],
] as const;

for (const [path, creditTest] of [
  ["/", publicTest],
  ["/settings", test],
] as const) {
  creditTest(
    `footer: creator credit opens the X profile from ${path}`,
    async ({ page, context }) => {
      await context.route("https://x.com/itsCzar16", (route) =>
        route.fulfill({
          contentType: "text/html",
          body: "<title>X profile</title>",
        }),
      );
      await page.goto(path);
      const credit = page
        .locator("[data-site-footer]")
        .getByRole("link", { name: "Made by Czarl6", exact: true });
      await expect(credit).toBeVisible();
      const popupPromise = page.waitForEvent("popup");
      await credit.click();
      const popup = await popupPromise;
      await expect(popup).toHaveURL("https://x.com/itsCzar16");
      await popup.close();
    },
  );
}

async function canvasImage(page: Page) {
  return page
    .locator("[data-site-footer] canvas")
    .evaluate((canvas: HTMLCanvasElement) => canvas.toDataURL());
}
async function checkFooter(page: Page, info: TestInfo, name: string) {
  const footer = page.locator("[data-site-footer]");
  const canvas = footer.locator("canvas");
  await expect(canvas).toHaveAttribute("height", /[1-9]/);
  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
  await expect(footer.getByRole("heading")).toHaveCount(3);
  await expect(
    footer.getByRole("heading", { name: "Send outreach that feels personal." }),
  ).toHaveCount(0);
  for (const name of ["Start sending", "View allowances"])
    await expect(footer.getByRole("link", { name, exact: true })).toHaveCount(
      0,
    );
  for (const column of ["Product", "Support", "Legal"])
    await expect(
      footer.getByRole("navigation", { name: column, exact: true }),
    ).toBeVisible();
  const primary = footer.getByRole("link", { name: "Templates", exact: true });
  for (const [label, href] of [
    ["Mailloop home", "/"],
    ["Templates", "/templates"],
    ["Contacts", "/contacts"],
    ["Send queue", "/history"],
    ["Allowances", "/usage"],
    ["Help center", "/help"],
    ["FAQ", "/help#faq"],
    ["Contact us", "/contact"],
    ["Privacy", "/privacy"],
    ["Terms", "/terms"],
    ["Made by Czarl6", "https://x.com/itsCzar16"],
  ]) {
    const link = footer.getByRole("link", { name: label, exact: true });
    await expect(link).toBeVisible();
    await expect(link).toHaveAttribute("href", href);
    await link.focus();
    await expect(link).toHaveCSS("outline-width", "2px");
    await expect(link).toHaveCSS("outline-offset", "3px");
  }
  const separatorColor = await footer.evaluate((element) => {
    const probe = document.createElement("span");
    probe.style.color =
      "color-mix(in srgb, var(--landing-muted) 85%, transparent)";
    element.append(probe);
    const color = getComputedStyle(probe).color;
    probe.remove();
    return color;
  });
  await expect(footer).toHaveCSS("border-top-style", "dotted");
  await expect(footer).toHaveCSS("border-top-width", "1px");
  await expect(footer).toHaveCSS("border-top-color", separatorColor);
  await expect(footer.locator("[data-footer-utility]")).toHaveCSS(
    "border-top-width",
    "0px",
  );

  const brand = footer.getByRole("link", { name: "Mailloop home" });
  const brandBox = (await brand.boundingBox())!;
  const productBox = (await footer
    .getByRole("navigation", { name: "Product", exact: true })
    .boundingBox())!;
  const supportBox = (await footer
    .getByRole("navigation", { name: "Support", exact: true })
    .boundingBox())!;
  expect(
    Math.abs(brandBox.x + brandBox.width / 2 - page.viewportSize()!.width / 2),
  ).toBeLessThan(1);
  if (page.viewportSize()!.width > 860) {
    expect(productBox.x + productBox.width).toBeLessThan(brandBox.x);
    expect(supportBox.x).toBeGreaterThan(brandBox.x + brandBox.width);
    const legalBox = (await footer
      .getByRole("navigation", { name: "Legal", exact: true })
      .boundingBox())!;
    const wordmarkCenter = brandBox.y + brandBox.height / 2;
    for (const group of [productBox, supportBox, legalBox]) {
      expect(
        Math.abs(group.y + group.height / 2 - wordmarkCenter),
      ).toBeLessThan(1);
    }
  } else {
    expect(brandBox.y + brandBox.height).toBeLessThan(productBox.y);
    expect(Math.abs(productBox.y - supportBox.y)).toBeLessThan(1);
    const legalBox = (await footer
      .getByRole("navigation", { name: "Legal", exact: true })
      .boundingBox())!;
    expect(legalBox.y).toBeGreaterThan(supportBox.y + supportBox.height);
    expect(legalBox.x).toBe(supportBox.x);
  }
  await expect(footer).toHaveCSS("box-shadow", "none");
  await expect(footer).toHaveCSS("border-radius", "0px");
  await expect(primary).toHaveCSS("background-image", "none");
  await expect(primary).toHaveCSS("box-shadow", "none");
  expect(
    await page.evaluate(() => document.documentElement.scrollWidth),
  ).toBeLessThanOrEqual(page.viewportSize()!.width);
  const metrics = await footer.evaluate((element) => {
    const style = getComputedStyle(element);
    return {
      width: element.getBoundingClientRect().width,
      panel: style.backgroundColor,
      pageBackground: getComputedStyle(
        element.closest(".landing") ?? document.body,
      ).backgroundColor,
    };
  });
  expect(metrics.width).toBe(page.viewportSize()!.width);
  expect(metrics.panel).toBe(metrics.pageBackground);
  await page.evaluate(() => {
    (document.activeElement as HTMLElement)?.blur();
    window.scrollTo(0, document.body.scrollHeight);
  });
  await info.attach(`${name}-footer`, {
    body: await footer.screenshot({
      path: info.outputPath(`${name}-footer.png`),
      style: "nextjs-portal, .help-launcher { display:none }",
    }),
    contentType: "image/png",
  });
  await primary.focus();
  await expect(primary).toHaveCSS("outline-width", "2px");
  await expect(primary).toHaveCSS("outline-offset", "3px");
}

async function checkWorkspaceFooter(page: Page, info: TestInfo, name: string) {
  const footer = page.locator("[data-site-footer]");
  await expect(footer).toHaveAttribute("data-footer-variant", "workspace");
  await expect(footer.locator("canvas")).toHaveAttribute("height", /[1-9]/);
  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
  await expect(footer.getByRole("heading")).toHaveCount(0);
  for (const label of ["Start sending", "View allowances", "Send queue", "FAQ"])
    await expect(
      footer.getByRole("link", { name: label, exact: true }),
    ).toHaveCount(0);
  for (const text of [
    "Personalized outreach, made easy.",
    "All systems running",
  ])
    await expect(footer.getByText(text, { exact: true })).toHaveCount(0);
  const destinations = [
    ["mailloop", "/"],
    ["Help center", "/help"],
    ["Contact us", "/contact"],
    ["Privacy", "/privacy"],
    ["Terms", "/terms"],
    ["Made by Czarl6", "https://x.com/itsCzar16"],
  ];
  for (const [label, href] of destinations) {
    const link = footer.getByRole("link", { name: label, exact: true });
    await expect(link).toBeVisible();
    await expect(link).toHaveAttribute("href", href);
    await link.focus();
    await expect(link).toHaveCSS("outline-width", "2px");
    await expect(link).toHaveCSS("outline-offset", "3px");
  }
  await expect(
    footer.getByRole("link", { name: "mailloop", exact: true }),
  ).toHaveCSS("font-size", "16px");
  const metrics = await footer.evaluate((element) => {
    const container = element.querySelector(".page-container")!;
    const main = document.querySelector("main.page-container")!;
    const row = container.firstElementChild!;
    const canvas = element.querySelector("canvas")!;
    return {
      height: element.getBoundingClientRect().height,
      canvasHeight: canvas.getBoundingClientRect().height,
      canvasWidth: canvas.getBoundingClientRect().width,
      left: container.getBoundingClientRect().left,
      mainLeft: main.getBoundingClientRect().left,
      width: container.getBoundingClientRect().width,
      mainWidth: main.getBoundingClientRect().width,
      background: getComputedStyle(element).backgroundColor,
      pageBackground: getComputedStyle(document.body).backgroundColor,
      rowHeight: row.getBoundingClientRect().height,
    };
  });
  expect(metrics.left).toBe(metrics.mainLeft);
  expect(metrics.width).toBe(metrics.mainWidth);
  expect(metrics.background).toBe(metrics.pageBackground);
  expect(metrics.canvasWidth).toBeLessThanOrEqual(480);
  expect(metrics.canvasHeight).toBeLessThanOrEqual(123);
  const brand = footer.getByRole("link", {
    name: "Mailloop home",
    exact: true,
  });
  await expect(brand).toHaveAttribute("href", "/");
  await brand.focus();
  await expect(brand).toHaveCSS("outline-width", "2px");
  await expect(brand).toHaveCSS("outline-offset", "3px");
  const brandBox = (await brand.boundingBox())!;
  const support = (await footer
    .getByRole("navigation", { name: "Support", exact: true })
    .boundingBox())!;
  const legal = (await footer
    .getByRole("navigation", { name: "Legal", exact: true })
    .boundingBox())!;
  const utility = footer.locator("[data-footer-utility]");
  const utilityBox = (await utility.boundingBox())!;
  expect(
    Math.abs(brandBox.x + brandBox.width / 2 - page.viewportSize()!.width / 2),
  ).toBeLessThan(1);
  if (page.viewportSize()!.width > 860) {
    expect(support.x + support.width).toBeLessThanOrEqual(brandBox.x);
    expect(legal.x).toBeGreaterThanOrEqual(brandBox.x + brandBox.width);
    expect(
      Math.abs(support.y + support.height / 2 - legal.y - legal.height / 2),
    ).toBeLessThan(1);
  } else {
    expect(brandBox.y + brandBox.height).toBeLessThan(support.y);
    expect(Math.abs(support.y - legal.y)).toBeLessThan(1);
  }
  expect(utilityBox.y).toBeGreaterThan(support.y + support.height);
  expect(utilityBox.y).toBeGreaterThan(brandBox.y + brandBox.height);
  const separatorColor = await footer.evaluate((element) => {
    const probe = document.createElement("span");
    probe.style.color =
      "color-mix(in srgb, var(--muted-foreground) 85%, transparent)";
    element.append(probe);
    const color = getComputedStyle(probe).color;
    probe.remove();
    return color;
  });
  for (const separator of [footer]) {
    await expect(separator).toHaveCSS("border-top-style", "dotted");
    await expect(separator).toHaveCSS("border-top-width", "1px");
    await expect(separator).toHaveCSS("border-top-color", separatorColor);
  }
  await expect(
    footer.getByRole("link", { name: "Help center", exact: true }),
  ).toHaveCSS("font-size", "14.5px");
  await expect(utility).toHaveCSS("font-size", "13.5px");
  await expect(utility).toHaveCSS("border-top-width", "0px");
  await page.evaluate(() => {
    (document.activeElement as HTMLElement)?.blur();
    window.scrollTo(0, document.body.scrollHeight);
  });
  expect(
    await page.evaluate(() => document.documentElement.scrollWidth),
  ).toBeLessThanOrEqual(page.viewportSize()!.width);
  await info.attach(`${name}-compact-footer`, {
    body: await footer.screenshot({
      path: info.outputPath(`${name}-compact-footer.png`),
      style: "nextjs-portal, .help-launcher { display:none }",
    }),
    contentType: "image/png",
  });
}

for (const [name, appearance, mode] of themes) {
  test(`footer: ${name} workspace`, async ({ page }, info) => {
    const errors: string[] = [];
    page.on("pageerror", (error) => errors.push(error.message));
    await page.setViewportSize({
      width: info.project.name === "mobile" ? 390 : 1440,
      height: 1000,
    });
    await page.emulateMedia({ reducedMotion: "reduce" });
    await page.addInitScript(
      ({ appearance, mode }) => {
        localStorage.setItem("mailloop-appearance", appearance);
        localStorage.setItem("mailloop-theme", mode);
      },
      { appearance, mode },
    );
    await page.goto("/settings");
    await expect(page.locator("html")).toHaveAttribute(
      "data-appearance",
      appearance,
    );
    await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
    for (const width of [1440, 390, 320, 860, 861]) {
      await page.setViewportSize({ width, height: 1000 });
      await expect
        .poll(() =>
          page
            .locator("[data-site-footer] canvas")
            .evaluate((canvas: HTMLCanvasElement) =>
              Math.abs(
                canvas.width / Math.min(devicePixelRatio, 2) -
                  canvas.getBoundingClientRect().width,
              ),
            ),
        )
        .toBeLessThan(1);
      await checkWorkspaceFooter(page, info, `${name}-${width}`);
    }
    const visibility = await page
      .locator("[data-site-footer] canvas")
      .evaluate((canvas: HTMLCanvasElement) => {
        const pixels = canvas
          .getContext("2d")!
          .getImageData(0, 0, canvas.width, canvas.height).data;
        const rows: number[] = [];
        for (let y = 0; y < canvas.height; y++) {
          let alpha = 0;
          for (let x = 0; x < canvas.width; x++)
            alpha = Math.max(alpha, pixels[(y * canvas.width + x) * 4 + 3]);
          if (alpha > 0) rows.push(alpha);
        }
        const band = Math.max(1, Math.floor(rows.length / 3));
        const average = (values: number[]) =>
          values.reduce((sum, value) => sum + value, 0) / values.length;
        return {
          top: average(rows.slice(0, band)),
          bottom: average(rows.slice(-band)),
        };
      });
    // Upper glyphs stay readable in both light palettes; the lower fade is retained.
    expect(visibility.top).toBeGreaterThan(70);
    expect(visibility.bottom).toBeGreaterThan(5);
    expect(visibility.bottom / visibility.top).toBeLessThan(0.65);
    const finished = await canvasImage(page);
    await page.waitForTimeout(150);
    expect(await canvasImage(page)).toBe(finished);
    // Attribute changes must recolor even when motion is disabled.
    await page.evaluate(() => {
      document.documentElement.dataset.theme =
        document.documentElement.dataset.theme === "dark" ? "light" : "dark";
    });
    await expect.poll(() => canvasImage(page)).not.toBe(finished);
    const recolored = await canvasImage(page);
    await page.evaluate(() => {
      document.documentElement.dataset.appearance =
        document.documentElement.dataset.appearance === "purple"
          ? "vercel"
          : "purple";
    });
    await expect.poll(() => canvasImage(page)).not.toBe(recolored);
    await page.evaluate(
      ({ appearance, mode }) => {
        document.documentElement.dataset.appearance = appearance;
        document.documentElement.dataset.theme = mode;
        window.scrollTo(0, 0);
      },
      { appearance, mode },
    );
    await page.emulateMedia({ reducedMotion: "no-preference" });
    await page.waitForTimeout(300);
    const beforeScroll = await canvasImage(page);
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    await expect.poll(() => canvasImage(page)).not.toBe(beforeScroll);
    await page.waitForTimeout(1200);
    expect(errors).toEqual([]);
    await page.goto("/usage");
    await expect(page.locator("[data-site-footer] canvas")).toHaveAttribute(
      "height",
      /[1-9]/,
    );
    expect(errors).toEqual([]);
  });
}

test("footer: workspace navigation shows it only on Usage and Settings", async ({
