  const navigation = page.getByRole("navigation", { name: "Main navigation" });
  for (const [name, visible] of [
    ["History", false],
    ["Templates", false],
    ["Usage", true],
    ["Contacts", false],
    ["Settings", true],
    ["Compose", false],
  ] as const) {
    await navigation.getByRole("link", { name }).click();
    await expect(page).toHaveURL(new RegExp(`/${name.toLowerCase()}$`));
