for (const mode of ["light", "dark"]) {
  publicTest(
    `footer: landing ${mode} scroll assembly`,
    async ({ page }, info) => {
      const errors: string[] = [];
      page.on("pageerror", (error) => errors.push(error.message));
      await page.setViewportSize({
        width: info.project.name === "mobile" ? 390 : 1440,
        height: 1000,
      });
      await page.emulateMedia({ reducedMotion: "no-preference" });
      await page.addInitScript(
        (mode) => localStorage.setItem("mailloop-theme", mode),
        mode,
      );
      await page.goto("/");
      await expect(page.locator("[data-site-footer] canvas")).toHaveAttribute(
        "height",
        /[1-9]/,
      );
      const empty = await canvasImage(page);
      await page
        .locator("[data-site-footer]")
        .evaluate((footer) =>
          window.scrollTo(
            0,
            footer.getBoundingClientRect().top + window.scrollY - 100,
          ),
        );
      await expect.poll(() => canvasImage(page)).not.toBe(empty);
      await checkFooter(page, info, `landing-${mode}`);
      expect(errors).toEqual([]);
      // Assembly at page bottom should cover the same glyphs as the static word.
      await page.waitForTimeout(1200);
      const alphaCoverage = () =>
        page
          .locator("[data-site-footer] canvas")
          .evaluate((canvas: HTMLCanvasElement) => {
            const pixels = canvas
              .getContext("2d")!
              .getImageData(0, 0, canvas.width, canvas.height).data;
            let alpha = 0;
            for (let i = 3; i < pixels.length; i += 4) alpha += pixels[i];
            return alpha;
          });
      const assembled = await alphaCoverage();
      await page.emulateMedia({ reducedMotion: "reduce" });
      await page.waitForTimeout(100);
      const staticCoverage = await alphaCoverage();
      expect(staticCoverage).toBeGreaterThan(0);
      expect(assembled / staticCoverage).toBeGreaterThan(0.99);
      expect(assembled / staticCoverage).toBeLessThan(1.01);
      expect(errors).toEqual([]);
      await info.attach(`assembled-${mode}`, {
        body: await page.locator("[data-site-footer]").screenshot({
          path: info.outputPath(`assembled-${mode}.png`),
          style: "nextjs-portal, .help-launcher { display:none }",
        }),
        contentType: "image/png",
      });
    },
  );
}

test("footer: Free and Premium share the same appearance", async ({
  page,
  themeUser,
}) => {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await setThemeQuotaGating(true);
  await page.goto("/settings");
  const footer = page.locator("[data-site-footer]");
  const premium = await footer.evaluate((element) => ({
    html: element.innerHTML.replace(/<canvas[^>]*>/, "<canvas>"),
    background: getComputedStyle(element).backgroundColor,
  }));
  await setThemePlan(themeUser, "FREE");
  await page.reload();
  await expect(footer.locator("canvas")).toHaveAttribute("height", /[1-9]/);
  const free = await footer.evaluate((element) => ({
    html: element.innerHTML.replace(/<canvas[^>]*>/, "<canvas>"),
    background: getComputedStyle(element).backgroundColor,
  }));
  expect(free).toEqual(premium);
});

