for (const [name, appearance, mode] of themes) {
  publicTest(
    `footer: centered landing ${name} responsive reduced motion`,
    async ({ page }, info) => {
      await page.emulateMedia({ reducedMotion: "reduce" });
      await page.addInitScript(
        ({ appearance, mode }) => {
          localStorage.setItem("mailloop-appearance", appearance);
          localStorage.setItem("mailloop-theme", mode);
        },
        { appearance, mode },
      );
      await page.goto("/");
      for (const width of [1440, 390, 320, 860, 861]) {
        await page.setViewportSize({ width, height: 1000 });
        await expect
          .poll(async () => {
            return page
              .locator("[data-site-footer] canvas")
              .evaluate((canvas: HTMLCanvasElement) =>
                Math.abs(
                  canvas.width / Math.min(devicePixelRatio, 2) -
                    canvas.getBoundingClientRect().width,
                ),
              );
          })
          .toBeLessThan(1);
        await checkFooter(page, info, `${appearance}-${mode}-${width}`);
        const opacity = await page
          .locator("[data-site-footer] canvas")
          .evaluate((canvas: HTMLCanvasElement) => {
            const pixels = canvas
              .getContext("2d")!
              .getImageData(0, 0, canvas.width, canvas.height).data;
            // Row maxima measure the gradient independently of glyph coverage.
            const rows: number[] = [];
            for (let y = 0; y < canvas.height; y++) {
              let alpha = 0;
              for (let x = 0; x < canvas.width; x++) {
                alpha = Math.max(alpha, pixels[(y * canvas.width + x) * 4 + 3]);
              }
              if (alpha > 0) rows.push(alpha);
            }
            const band = Math.max(1, Math.floor(rows.length / 3));
            const average = (values: number[]) =>
              values.reduce((sum, value) => sum + value, 0) / values.length;
            return {
              top: average(rows.slice(0, band)),
              bottom: average(rows.slice(-band)),
            };
          });
        expect(opacity.top).toBeGreaterThan(0);
        expect(opacity.bottom).toBeGreaterThan(0);
        expect(opacity.bottom / opacity.top).toBeLessThan(0.65);
        const finished = await canvasImage(page);
        await page.waitForTimeout(180);
        expect(await canvasImage(page)).toBe(finished);
      }
      const finished = await canvasImage(page);
      await page.evaluate(() => {
        document.documentElement.dataset.theme =
          document.documentElement.dataset.theme === "dark" ? "light" : "dark";
      });
      await expect.poll(() => canvasImage(page)).not.toBe(finished);
    },
  );
}

test("footer: theme switching recolors particles during assembly", async ({
  page,
}) => {
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.goto("/settings");
  const canvas = page.locator("[data-site-footer] canvas");
  await expect(canvas).toHaveAttribute("height", /[1-9]/);
  await page.evaluate(() => {
    document.documentElement.dataset.appearance = "purple";
    document.documentElement.dataset.theme = "dark";
    const stage = document
      .querySelector("[data-site-footer] canvas")!
      .getBoundingClientRect();
    window.scrollBy(0, stage.top - innerHeight + stage.height * 0.65);
  });
  const saturation = () =>
    canvas.evaluate((canvas: HTMLCanvasElement) => {
      const data = canvas
        .getContext("2d")!
        .getImageData(0, 0, canvas.width, canvas.height).data;
      let sum = 0,
        count = 0;
      for (let i = 0; i < data.length; i += 4)
        if (data[i + 3] > 40) {
          sum +=
            Math.max(data[i], data[i + 1], data[i + 2]) -
            Math.min(data[i], data[i + 1], data[i + 2]);
          count++;
        }
      return count ? sum / count : -1;
    });
  await expect.poll(saturation).toBeGreaterThan(25);
  await page.evaluate(() => {
    document.documentElement.dataset.appearance = "vercel";
  });
  await expect.poll(saturation).toBeGreaterThanOrEqual(0);
  await expect.poll(saturation).toBeLessThan(3);
  await page.evaluate(() => {
    document.documentElement.dataset.appearance = "purple";
  });
  await expect.poll(saturation).toBeGreaterThan(25);
});

async function checkFooterInteraction(page: Page, info: TestInfo) {
  const footer = page.locator("[data-site-footer]");
  const canvas = footer.locator("canvas");
  const home = footer.getByRole("link", { name: "Mailloop home", exact: true });
  const link = footer.getByRole("link", { name: "Help center", exact: true });
  const underline = () =>
    link.evaluate((el) => getComputedStyle(el, "::after").transform);
  const capture = async (state: string) => {
    await info.attach(state, {
      body: await footer.screenshot({
        path: info.outputPath(`${state}.png`),
        style: "nextjs-portal, .help-launcher { display:none }",
      }),
      contentType: "image/png",
    });
  };
  await expect(canvas).toHaveAttribute("height", /[1-9]/);
  await page.mouse.move(0, 0);
  // Hover or keyboard focus during assembly queues one sweep.
  await home.evaluate((el) => {
    const stage = el.querySelector("canvas")!.getBoundingClientRect();
    window.scrollBy(0, stage.top - innerHeight + stage.height * 0.6);
  });
  if (info.project.name === "desktop") {
    const box = (await home.boundingBox())!;
    await page.mouse.move(box.x + box.width / 2, box.y + box.height * 0.3);
  } else {
    await home.evaluate((el: HTMLElement) => el.focus({ preventScroll: true }));
  }
  await expect(canvas).toHaveAttribute("data-wordmark-state", "assembling");
  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
  if (info.project.name === "desktop") {
    // Follow the link as scrolling moves it away from the initial pointer.
    const box = (await home.boundingBox())!;
    await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  }
  await expect(canvas).toHaveAttribute("data-wordmark-state", "sweeping");
  await expect(canvas).toHaveAttribute("data-wordmark-state", "idle");
  await home.evaluate((el: HTMLElement) => el.blur());
  await page.mouse.move(0, 0);
  const idle = await canvasImage(page);
  await capture("idle");
  await page.waitForTimeout(1500);
  expect(await canvasImage(page)).toBe(idle); // No repeating shine.

  // Keep the animation clock deterministic for midpoint captures and re-entry.
  const clockTime = await page.evaluate(() => Date.now());
  await page.clock.pauseAt(clockTime + 1000);
  await home.focus();
  await page.keyboard.press("Tab");
  await page.keyboard.press("Shift+Tab");
  await expect(home).toBeFocused();
  await page.clock.runFor(700);
  await expect(canvas).toHaveAttribute("data-wordmark-state", "sweeping");
  expect(await canvasImage(page)).not.toBe(idle);
  await capture("mid-focus");
  await page.evaluate(() => {
    const root = document.documentElement;
    root.dataset.theme = root.dataset.theme === "dark" ? "light" : "dark";
  });
  await expect(canvas).toHaveAttribute("data-wordmark-state", "sweeping");
  await page.evaluate(() => {
    const root = document.documentElement;
    root.dataset.theme = root.dataset.theme === "dark" ? "light" : "dark";
  });
  await home.evaluate((el: HTMLElement) => el.blur());
  await home.focus();
  await page.clock.runFor(200);
  // The slower sweep remains active beyond the previous 850ms duration.
  await expect(canvas).toHaveAttribute("data-wordmark-state", "sweeping");
  await page.clock.runFor(550);
  // Re-entry during the sweep neither restarts it nor queues another.
  await expect(canvas).toHaveAttribute("data-wordmark-state", "idle");
  expect(await canvasImage(page)).toBe(idle);
  await capture("completed-focus");
  await home.evaluate((el: HTMLElement) => el.blur());
  await capture("exit");

  await link.focus();
  await page.clock.runFor(250);
  await expect.poll(underline).toBe("matrix(1, 0, 0, 1, 0, 0)");
  await expect(link).toHaveCSS("outline-width", "2px");
  await link.evaluate((el: HTMLElement) => el.blur());
  await page.clock.runFor(250);
  await expect.poll(underline).toBe("matrix(0, 0, 0, 1, 0, 0)");
  const credit = footer.getByRole("link", { name: "Made by Czarl6" });
  await credit.focus();
  await page.clock.runFor(250);
  await expect
    .poll(() =>
      credit.evaluate((el) => getComputedStyle(el, "::after").transform),
    )
    .toBe("matrix(1, 0, 0, 1, 0, 0)");
  await credit.evaluate((el: HTMLElement) => el.blur());

  if (info.project.name === "desktop") {
    await home.hover();
    await page.clock.runFor(700);
    await expect(canvas).toHaveAttribute("data-wordmark-state", "sweeping");
    await capture("mid-hover");
    await page.mouse.move(0, 0);
    await home.hover();
    await page.clock.runFor(200);
    await expect(canvas).toHaveAttribute("data-wordmark-state", "sweeping");
    await page.clock.runFor(550);
    await expect(canvas).toHaveAttribute("data-wordmark-state", "idle");
    await capture("completed-hover");
    await page.mouse.move(0, 0);
    await home.hover();
    await page.clock.runFor(100);
    await expect(canvas).toHaveAttribute("data-wordmark-state", "sweeping");
    await page.clock.runFor(1350);
    await page.mouse.move(0, 0);
    await link.hover();
    await page.clock.runFor(250);
    await expect.poll(underline).toBe("matrix(1, 0, 0, 1, 0, 0)");
    await page.mouse.move(0, 0);
    await page.clock.runFor(250);
    await expect.poll(underline).toBe("matrix(0, 0, 0, 1, 0, 0)");
  } else {
    // Prevent navigation so a real touch can be inspected after release.
    await home.evaluate((el) =>
      el.addEventListener("click", (event) => event.preventDefault()),
    );
    await home.tap();
    await page.clock.runFor(1500);
    await expect(canvas).toHaveAttribute("data-wordmark-state", "idle");
    expect(await canvasImage(page)).toBe(idle);
  }

  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.keyboard.press("Tab");
  await home.focus();
  await expect(canvas).toHaveAttribute("data-wordmark-state", "highlight");
  const highlight = await canvasImage(page);
  expect(highlight).not.toBe(idle);
  await capture("reduced-motion-highlight");
  await page.clock.runFor(1200);
  expect(await canvasImage(page)).toBe(highlight);
  await home.evaluate((el: HTMLElement) => el.blur());
  expect(await canvasImage(page)).toBe(idle);
  await link.focus();
  await expect.poll(underline).toBe("matrix(1, 0, 0, 1, 0, 0)");
  await expect(link).toHaveCSS("transition-duration", "0s");
  await link.evaluate((el: HTMLElement) => el.blur());
  await expect.poll(underline).toBe("matrix(0, 0, 0, 1, 0, 0)");
}

for (const [name, appearance, mode] of themes) {
  for (const variant of ["landing", "workspace"] as const) {
    const route = variant === "landing" ? "/" : "/settings";
    const interactionTest = variant === "landing" ? publicTest : test;
    interactionTest(
      `footer: ${name} ${variant} hover and focus`,
      async ({ page }, info) => {
        await page.setViewportSize({
          width: info.project.name === "mobile" ? 320 : 1440,
          height: 1000,
        });
        await page.emulateMedia({ reducedMotion: "no-preference" });
        await page.addInitScript(
          ({ appearance, mode }) => {
            localStorage.setItem("mailloop-appearance", appearance);
            localStorage.setItem("mailloop-theme", mode);
          },
          { appearance, mode },
        );
        await page.clock.install();
        await page.goto(route);
        await checkFooterInteraction(page, info);
      },
    );
  }
}

